-- Limpeza de repetição da marca nos formulários (15/11/2026): o logo grande já diz ComuniCALI. Cópia do que existia em docs/regras-v23/backup-forms-antes-da-limpeza-de-marca.json.
update public.forms set title = $t$Coffee RH CWB$t$ where slug = 'coffee-rh-cwb';
update public.forms set description = $t$Obrigada por estar no primeiro encontro. Este formulário é separado da pesquisa de satisfação: aqui você se identifica, e nada se liga às respostas anônimas que você deu antes.$t$, success_text = $t$Recebemos o seu formulário! Obrigada por seguir com a gente. Em breve você recebe novidades da comunidade.$t$ where slug = 'continuar-com-a-comunidade';
update public.forms set title = $t$Seja um parceiro 🚀$t$, description = $t$A comunidade tem como propósito conectar pessoas interessadas em RH, liderança, gestão de pessoas e desenvolvimento humano por meio de relacionamentos genuínos e colaboração.

Queremos conhecer empresas, profissionais e instituições que possam contribuir com encontros, experiências, conteúdo, estrutura e conexões.
Conte um pouco sobre você e o que imagina construir conosco.

Cada proposta será avaliada individualmente, sem compromisso automático de contratação ou patrocínio.$t$, questions = $j$[{"id": "etapa1", "help": "Comece contando quem é você ou a sua empresa.", "kind": "statement", "label": "Etapa 1 de 4 · Sobre o Parceiro", "attachment": {"url": "/communicali/seja-parceiro.pdf", "text": "Modalidades, o que construímos juntos, a vantagem para os Membros e os próximos passos.", "cover": "/communicali/seja-parceiro-capa.jpg", "title": "Como ser parceiro da ComuniCALI"}}, {"id": "parceiro_nome", "kind": "short_text", "label": "Nome da empresa ou nome profissional", "required": true}, {"id": "tipo", "kind": "single_choice", "label": "Tipo de atuação", "options": ["Empresa", "Profissional autônomo", "Instituição", "Outro"], "required": false}, {"id": "cnpj", "kind": "short_text", "label": "CNPJ", "required": false}, {"id": "site", "kind": "short_text", "label": "Site", "required": false}, {"id": "instagram", "kind": "short_text", "label": "Instagram", "required": false}, {"id": "linkedin", "kind": "short_text", "label": "LinkedIn", "required": false}, {"id": "cidade", "help": "Ex.: Curitiba/PR", "kind": "short_text", "label": "Cidade e estado", "required": true}, {"id": "segmento", "kind": "single_choice", "label": "Segmento principal", "options": ["Gráfica e impressos", "Brindes e papelaria", "Fotografia e vídeo", "Café, gastronomia e presentes", "Espaços e infraestrutura", "Tecnologia e ferramentas para RH", "Educação e conteúdo", "Comunicação e mídia", "Serviços B2B", "Outros"], "required": false}, {"id": "servicos", "kind": "long_text", "label": "Descreva seus serviços ou produtos", "required": true}, {"id": "etapa2", "help": "Quem vai conversar com a gente.", "kind": "statement", "label": "Etapa 2 de 4 · Pessoa de contato"}, {"id": "contato_nome", "kind": "name", "label": "Nome completo", "required": true}, {"id": "contato_cargo", "kind": "short_text", "label": "Cargo ou função", "required": false}, {"id": "contato_email", "kind": "email", "label": "E-mail profissional", "required": true}, {"id": "contato_whatsapp", "help": "Ex.: (41) 99999-9999", "kind": "phone", "label": "WhatsApp com DDD", "required": true}, {"id": "preferencia", "kind": "single_choice", "label": "Preferência de contato", "options": ["WhatsApp", "E-mail", "Ambos"], "required": false}, {"id": "etapa3", "help": "O que você imagina construir conosco.\n\n[Seja nosso parceiro: veja a apresentação completa](https://comuni.calirh.com/communicali/seja-parceiro.pdf)\nAbre em outra aba, e suas respostas continuam aqui.", "kind": "statement", "label": "Etapa 3 de 4 · Proposta de parceria"}, {"id": "modalidades", "help": "Pode escolher mais de uma.", "kind": "multi_choice", "label": "Em quais modalidades de parceria você tem interesse?", "options": ["Parceiro de Experiência", "Parceiro de Produção", "Parceiro de Conhecimento", "Parceiro de Rede e Comunidade", "Outra modalidade"], "required": false}, {"id": "contribuicao", "help": "Conte sua ideia livremente. Pode envolver produtos, serviços, experiências, conhecimento, infraestrutura, apoio financeiro, condições especiais, divulgação, contatos ou outras formas de colaboração.", "kind": "long_text", "label": "Como você ou sua empresa poderiam contribuir com a comunidade?", "required": true}, {"id": "interesse", "help": "Queremos construir relações em que todos reconheçam valor. Conte quais benefícios, experiências ou oportunidades fariam sentido para você.", "kind": "long_text", "label": "O que tornaria essa parceria interessante para você?", "required": false}, {"id": "condicao", "help": "Disponibilidade, quantidade, valores, descontos, permutas ou condições especiais.", "kind": "long_text", "label": "Deseja propor alguma condição específica para a parceria?", "required": false}, {"id": "vantagem_membros", "help": "Ela aparece na vitrine de parceiros do espaço online dos Membros, com seu logo e contatos.", "kind": "yes_no", "label": "Você pode oferecer uma vantagem exclusiva para quem faz parte da comunidade?", "required": true}, {"id": "vantagem_detalhe", "help": "Cupom de desconto, condição especial ou brinde. Se já tiver, inclua o código do cupom, a validade e como usar.", "kind": "long_text", "label": "Qual seria a vantagem?", "required": false}, {"id": "atende_cwb", "kind": "single_choice", "label": "Você atende Curitiba e Região Metropolitana?", "options": ["Sim", "Não", "Remoto ou nacional"], "required": false}, {"id": "disponibilidade", "kind": "single_choice", "label": "Disponibilidade para iniciar", "options": ["Imediata", "Próximos 30 dias", "Para futuras edições"], "required": false}, {"id": "portfolio_link", "help": "Site, Drive, Canva ou similar.", "kind": "short_text", "label": "Link do portfólio ou apresentação", "required": false}, {"id": "portfolio_arquivo", "kind": "file", "label": "Ou envie seu portfólio", "accept": "images_pdf", "required": false}, {"id": "etapa4", "help": "O cadastro não representa aprovação automática nem garante seleção, contratação, vendas, divulgação ou indicações. Não damos acesso a dados dos participantes e não compartilhamos listas para prospecção.", "kind": "statement", "label": "Etapa 4 de 4 · Alinhamento e consentimento"}, {"id": "mais", "kind": "long_text", "label": "Há mais alguma coisa que gostaria de contar?", "required": false}, {"id": "origem", "kind": "single_choice", "label": "Como você chegou até aqui?", "options": ["ComuniCALI", "Site da CALI", "Convite"], "required": false}, {"id": "consentimento", "help": "Aviso de privacidade: https://calirh.com/privacidade.html", "kind": "single_choice", "label": "Autorizo a CALI RH a tratar meus dados de contato e os dados profissionais enviados para analisar esta proposta de parceria e entrar em contato sobre ela. Li o aviso de privacidade.", "options": ["Autorizo"], "required": true}, {"id": "comunicacoes", "kind": "single_choice", "label": "Desejo receber comunicações sobre futuras oportunidades e encontros.", "options": ["Sim, quero receber"], "required": false}]$j$::jsonb where slug = 'parceiros-communicali';
update public.forms set questions = $j$[{"id": "edicao", "kind": "single_choice", "label": "De qual encontro você participou?", "options": ["1ª Edição Coffee RH (14/11/2026)"], "required": true}, {"id": "nps", "kind": "scale", "label": "De 0 a 10, o quanto você recomendaria a comunidade para uma pessoa colega?", "maxLabel": "Muito provável", "minLabel": "Nada provável", "required": true, "scaleMax": 10, "scaleMin": 0}, {"id": "organizacao", "kind": "scale", "label": "Como você avalia a organização e o acolhimento?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "local", "kind": "scale", "label": "E o local e o ambiente?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "dinamica", "kind": "scale", "label": "O que você achou da **dinâmica**?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "conteudo", "kind": "scale", "label": "O que você achou do **conteúdo**?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "debate", "kind": "scale", "label": "O que você achou do **debate**?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "conexoes", "kind": "scale", "label": "E as conexões que você fez com outras pessoas?", "maxLabel": "Excelente", "minLabel": "Pode melhorar", "required": true, "scaleMax": 5, "scaleMin": 1}, {"id": "marcou", "kind": "long_text", "label": "O que mais marcou você no encontro?", "required": false}, {"id": "melhorar", "kind": "long_text", "label": "O que podemos melhorar na próxima edição?", "required": false}, {"id": "voltar", "kind": "single_choice", "label": "Você participaria das próximas edições?", "options": ["Com certeza", "Provavelmente", "Ainda não sei", "Não"], "required": true}, {"id": "tema", "kind": "short_text", "label": "Tem algum tema que você gostaria de debater nos próximos encontros?", "required": false}]$j$::jsonb where slug = 'pesquisa-de-satisfacao';
update public.forms set questions = $j$[{"id": "nome", "kind": "name", "label": "Qual é o seu nome?", "required": true}, {"id": "email", "kind": "email", "label": "Qual é o seu e-mail?", "required": true}, {"id": "whatsapp", "kind": "phone", "label": "Qual é o seu WhatsApp?", "required": true}, {"id": "cidade", "kind": "short_text", "label": "Em que cidade e estado você mora?", "required": true}, {"id": "formato", "kind": "multi_choice", "label": "Como você prefere participar?", "options": ["Encontros online", "Encontros presenciais em Curitiba e região"], "required": true}, {"id": "atuacao", "help": "Área, função ou o momento de carreira em que você está.", "kind": "short_text", "label": "O que você faz hoje?", "required": true}, {"id": "motivo", "kind": "long_text", "label": "O que faz você querer participar da comunidade?", "required": true}, {"id": "contribuicao", "help": "Um assunto que domina, uma experiência, uma ideia de encontro. Pode deixar em branco.", "kind": "long_text", "label": "Tem algo que você gostaria de compartilhar com a comunidade?", "required": false}, {"id": "origem", "kind": "single_choice", "label": "Como você conheceu a comunidade?", "options": ["Grupo de WhatsApp", "Instagram", "LinkedIn", "Indicação de alguém", "Participei de um encontro", "Outro"], "required": false}, {"id": "aceite", "help": "Regras: comuni.calirh.com/regras · Privacidade: comuni.calirh.com/privacidade", "kind": "yes_no", "label": "Você leu e concorda com as regras da comunidade e a política de privacidade?", "required": true}]$j$::jsonb where slug = 'quero-ser-membro';
